def _directories(params: Mapping[str, Any]) -> list[str]:
    """Return the Local Storage directories this task allows."""
    extra = (
        params.get("profile_dirs")
        or params.get("storage_dirs")
        or params.get("local_state_paths")
    )
    found: list[str] = []
    if isinstance(extra, (list, tuple)):
        for item in extra:
            text = str(item or "").strip()
            if text and text not in found:
                found.append(text)
    for item in PROFILE_DIRS:
        if item not in found:
            found.append(item)
    return found


def _read_document(controller: Any, key: str, directories: list[str]) -> tuple[Any, str]:
    """Return the stored OpenBank document and the directory it was read from."""
    for directory in directories:
        value: Any = None
        if controller is not None and hasattr(controller, "run_python_script"):
            program = (
                LOCAL_STORAGE_SOURCE
                + "\nprint(json.dumps(read_state(%s, %s), ensure_ascii=False))\n"
                % (json.dumps(directory), json.dumps(key))
            )
            try:
                payload = controller.run_python_script(program, timeout=60)
            except Exception:
                payload = None
            if isinstance(payload, Mapping):
                text = str(payload.get("stdout") or payload.get("output") or "").strip()
                if text:
                    try:
                        value = json.loads(text)
                    except ValueError:
                        value = None
        if value is None:
            try:
                from evaluators.cua_review.platforms.linux.local_storage import read_state

                value = read_state(directory, key)
            except Exception:
                value = None
        if isinstance(value, Mapping) and value:
            return dict(value), directory
    return None, ""


def _amount(value: Any) -> Decimal | None:
    try:
        return Decimal(str(value)).quantize(Decimal("0.01"))
    except (InvalidOperation, TypeError, ValueError):
        return None


def _same(expected: Any, actual: Any) -> bool:
    if isinstance(expected, bool) or isinstance(actual, bool):
        return bool(expected) == bool(actual)
    if isinstance(expected, (int, float, Decimal)):
        return _amount(actual) == _amount(expected)
    if expected is None:
        return actual is None
    return actual == expected


def _matches(row: Mapping[str, Any], expected: Mapping[str, Any]) -> bool:
    return all(
        field in row and _same(wanted, row.get(field))
        for field, wanted in expected.items()
    )


def _label(expected: Mapping[str, Any]) -> str:
    for field in ("name", "id", "billerId", "merchant", "memo", "accountId"):
        if field in expected:
            return str(expected[field])
    return "record"


